style_talk_index.css_content:
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800&family=Outfit:wght@500;600;700;800&family=JetBrains+Mono:wght@400;600&display=swap');

        :root {
            --bg-dark: #070b14;
            --bg-card: rgba(17, 25, 44, 0.82);
            --accent-blue: #38bdf8;
            --accent-indigo: #818cf8;
            --accent-teal: #2dd4bf;
            --accent-amber: #fbbf24;
            --accent-rose: #fb7185;
            --text-main: #f8fafc;
            --text-muted: #cbd5e1;
            --text-dim: #94a3b8;
            --border-subtle: rgba(148, 163, 184, 0.18);
        }

        * {
            box-sizing: border-box;
            margin: 0;
            padding: 0;
        }

        body {
            background: radial-gradient(circle at 18% 15%, #131d38 0%, #090e1a 55%, #050811 100%);
            color: var(--text-main);
            font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
            min-height: 100vh;
            display: flex;
            flex-direction: column;
            justify-content: space-between;
            line-height: 1.6;
            padding: 36px 24px;
        }

        .container {
            max-width: 1200px;
            margin: 0 auto;
            width: 100%;
        }

        .top-bar {
            display: flex;
            justify-content: space-between;
            align-items: center;
            flex-wrap: wrap;
            gap: 12px;
            margin-bottom: 32px;
            padding-bottom: 16px;
            border-bottom: 1px solid var(--border-subtle);
        }

        .top-bar .brand {
            display: flex;
            align-items: center;
            gap: 12px;
            font-family: 'Outfit', sans-serif;
            font-weight: 700;
            font-size: 1.05rem;
            color: var(--text-main);
            text-decoration: none;
        }

        .top-bar .brand span.badge-pill {
            background: rgba(56, 189, 248, 0.14);
            border: 1px solid rgba(56, 189, 248, 0.35);
            color: var(--accent-blue);
            font-size: 0.75rem;
            padding: 3px 10px;
            border-radius: 999px;
            text-transform: uppercase;
            letter-spacing: 0.06em;
        }

        .top-bar .nav-links {
            display: flex;
            gap: 10px;
            flex-wrap: wrap;
        }

        .top-bar .nav-links a {
            color: var(--text-muted);
            text-decoration: none;
            font-size: 0.85rem;
            font-weight: 600;
            padding: 6px 14px;
            border-radius: 999px;
            background: rgba(15, 23, 42, 0.7);
            border: 1px solid var(--border-subtle);
            transition: all 0.2s ease;
            display: inline-flex;
            align-items: center;
            gap: 6px;
        }

        .top-bar .nav-links a:hover {
            color: #fff;
            border-color: var(--accent-blue);
            background: rgba(56, 189, 248, 0.15);
        }

        .hero {
            text-align: center;
            max-width: 900px;
            margin: 0 auto 38px auto;
        }

        .hero-eyebrow {
            display: inline-flex;
            align-items: center;
            gap: 8px;
            background: rgba(56, 189, 248, 0.12);
            border: 1px solid rgba(56, 189, 248, 0.35);
            color: var(--accent-blue);
            font-size: 0.78rem;
            font-weight: 700;
            text-transform: uppercase;
            letter-spacing: 0.08em;
            padding: 6px 16px;
            border-radius: 999px;
            margin-bottom: 16px;
        }

        .hero h1 {
            font-family: 'Outfit', sans-serif;
            font-size: clamp(1.9rem, 3.5vw, 2.75rem);
            font-weight: 800;
            letter-spacing: -0.02em;
            line-height: 1.18;
            margin-bottom: 12px;
            background: linear-gradient(135deg, #ffffff 0%, #bae6fd 55%, #818cf8 100%);
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
        }

        .hero p {
            color: var(--text-muted);
            font-size: 1.02rem;
            max-width: 760px;
            margin: 0 auto;
        }

        /* Primary 2-Button Quick Launch Bar */
        .primary-cta-group {
            display: flex;
            justify-content: center;
            gap: 18px;
            flex-wrap: wrap;
            margin: 26px 0 10px 0;
        }

        .btn-launch {
            display: inline-flex;
            align-items: center;
            gap: 10px;
            padding: 14px 26px;
            border-radius: 12px;
            font-family: 'Outfit', sans-serif;
            font-size: 1rem;
            font-weight: 700;
            text-decoration: none;
            transition: all 0.22s ease;
            box-shadow: 0 10px 28px -8px rgba(0, 0, 0, 0.6);
        }

        .btn-launch-summary {
            background: linear-gradient(135deg, #0ea5e9 0%, #6366f1 100%);
            color: #ffffff;
            border: 1px solid rgba(186, 230, 253, 0.4);
        }

        .btn-launch-summary:hover {
            transform: translateY(-2px);
            box-shadow: 0 14px 32px -6px rgba(14, 165, 233, 0.45);
        }

        .btn-launch-talk {
            background: rgba(30, 41, 59, 0.9);
            color: #f8fafc;
            border: 1px solid rgba(45, 212, 191, 0.5);
        }

        .btn-launch-talk:hover {
            transform: translateY(-2px);
            background: rgba(45, 212, 191, 0.16);
            border-color: var(--accent-teal);
            box-shadow: 0 14px 32px -6px rgba(45, 212, 191, 0.28);
        }

        /* Dual Deck Grid */
        .decks-grid {
            display: grid;
            grid-template-columns: repeat(2, 1fr);
            gap: 26px;
            margin-bottom: 36px;
        }

        @media (max-width: 900px) {
            .decks-grid {
                grid-template-columns: 1fr;
            }
        }

        @media (max-width: 600px) {
            body {
                padding: 18px 14px;
            }
            .top-bar {
                flex-direction: column;
                align-items: flex-start;
            }
            .btn-launch {
                width: 100%;
                justify-content: center;
                text-align: center;
                padding: 12px 16px;
                font-size: 0.92rem;
            }
            .deck-card {
                padding: 20px 16px;
            }
            .download-row {
                grid-template-columns: 1fr;
            }
            footer {
                flex-direction: column;
                text-align: center;
            }
        }

        .deck-card {
            background: var(--bg-card);
            border: 1px solid var(--border-subtle);
            border-radius: 18px;
            padding: 28px;
            display: flex;
            flex-direction: column;
            justify-content: space-between;
            box-shadow: 0 16px 40px -12px rgba(0, 0, 0, 0.55);
            backdrop-filter: blur(12px);
            position: relative;
            overflow: hidden;
            transition: transform 0.22s ease, border-color 0.22s ease;
        }

        .deck-card:hover {
            transform: translateY(-3px);
        }

        .deck-card.card-summary {
            border-top: 4px solid var(--accent-blue);
        }

        .deck-card.card-talk {
            border-top: 4px solid var(--accent-teal);
        }

        .deck-header {
            display: flex;
            justify-content: space-between;
            align-items: center;
            gap: 10px;
            margin-bottom: 14px;
            flex-wrap: wrap;
        }

        .stage-badge {
            font-size: 0.74rem;
            font-weight: 700;
            text-transform: uppercase;
            letter-spacing: 0.07em;
            padding: 4px 12px;
            border-radius: 999px;
        }

        .badge-final {
            background: rgba(56, 189, 248, 0.16);
            color: var(--accent-blue);
            border: 1px solid rgba(56, 189, 248, 0.4);
        }

        .badge-committee {
            background: rgba(45, 212, 191, 0.15);
            color: var(--accent-teal);
            border: 1px solid rgba(45, 212, 191, 0.4);
        }

        .meta-pill {
            font-family: 'JetBrains Mono', monospace;
            font-size: 0.76rem;
            color: var(--text-dim);
            background: rgba(15, 23, 42, 0.75);
            padding: 4px 10px;
            border-radius: 6px;
            border: 1px solid var(--border-subtle);
        }

        .deck-card h2 {
            font-family: 'Outfit', sans-serif;
            font-size: 1.45rem;
            font-weight: 700;
            color: #fff;
            margin-bottom: 8px;
            line-height: 1.25;
        }

        .deck-card .subtitle {
            color: var(--text-muted);
            font-size: 0.9rem;
            margin-bottom: 16px;
        }

        .topic-list {
            list-style: none;
            margin: 0 0 22px 0;
            padding: 0;
        }

        .topic-list li {
            position: relative;
            padding-left: 22px;
            margin-bottom: 8px;
            font-size: 0.86rem;
            color: var(--text-muted);
        }

        .topic-list li i {
            position: absolute;
            left: 0;
            top: 4px;
            font-size: 0.8rem;
        }

        .card-summary .topic-list li i {
            color: var(--accent-blue);
        }

        .card-talk .topic-list li i {
            color: var(--accent-teal);
        }

        .card-actions {
            display: flex;
            flex-direction: column;
            gap: 10px;
            padding-top: 16px;
            border-top: 1px solid var(--border-subtle);
        }

        .btn-view-deck {
            display: inline-flex;
            align-items: center;
            justify-content: center;
            gap: 8px;
            padding: 12px 18px;
            border-radius: 10px;
            font-weight: 700;
            font-size: 0.92rem;
            text-decoration: none;
            transition: all 0.2s ease;
        }

        .card-summary .btn-view-deck {
            background: linear-gradient(135deg, #0ea5e9 0%, #6366f1 100%);
            color: #fff;
        }

        .card-summary .btn-view-deck:hover {
