            transform: translateY(-1px);
        }

        .card-talk .btn-view-deck {
            background: linear-gradient(135deg, #14b8a6 0%, #0284c7 100%);
            color: #fff;
        }

        .card-talk .btn-view-deck:hover {
            opacity: 0.94;
            transform: translateY(-1px);
        }

        .download-row {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 10px;
        }

        .btn-dl {
            display: inline-flex;
            align-items: center;
            justify-content: center;
