        }

        .btn-dl i.fa-file-pdf {
            color: #f87171;
        }

        footer {
            text-align: center;
            padding-top: 20px;
            border-top: 1px solid var(--border-subtle);
            color: var(--text-dim);
            font-size: 0.82rem;
            display: flex;
            justify-content: space-between;
            align-items: center;
            flex-wrap: wrap;
            gap: 12px;
        }

        footer a {
